package delivery
import (
 "context"
 "os"
 "testing"
 "time"
 "github.com/jackc/pgx/v5/pgxpool"
)
func TestIntegrationWatermarkInitialChildRoleIsolation(t *testing.T){
 dsn:=os.Getenv("PHOTO_TEST_DATABASE_URL");if dsn==""{t.Skip("isolated database migrated through01768 required")}
 ctx,cancel:=context.WithTimeout(context.Background(),20*time.Second);defer cancel()
 db,err:=pgxpool.New(ctx,dsn);if err!=nil{t.Fatal(err)};defer db.Close()
 for _,signature:=range []string{"photo.v30_watermark_placement_ready(bigint,bigint,bigint,bigint,jsonb)","photo.create_v30_watermark_sharpen_task(uuid,uuid,integer,integer,uuid,jsonb,text,bigint,text)","photo.create_v30_watermark_sharpen_task(uuid,uuid,integer,integer,uuid,jsonb,text,bigint)","photo.v30_watermark_derivative_profile(text,text,text)","photo.create_v30_watermark_derivative_initial_draft(uuid,uuid,integer,text,uuid,text,jsonb,text,bigint,text)","photo.lock_v30_watermark_retained_source(uuid,uuid,uuid,uuid,uuid,text,text)","photo.v30_watermark_retained_source_ready(uuid,uuid,uuid,uuid,uuid,text,text)","photo.v30_watermark_encode_completion_ready(uuid,uuid,text)","photo.v30_watermark_pending_child_slots(uuid,uuid,integer)","photo.v30_watermark_saved_continuation_params(uuid,uuid,integer,text,text)","photo.v30_watermark_child_sources(uuid,uuid,integer,text,integer)","photo.create_v30_watermark_initial_child_draft(uuid,uuid,integer,text,uuid,text,jsonb,text,bigint,text)","photo.v30_watermark_initial_transport_ready(uuid,uuid,integer,jsonb,text,text)","photo.activate_v30_watermark_initial_child(uuid,uuid,integer,text,uuid,text,text)","photo.commit_v30_watermark_initial_child(uuid,uuid,integer,text,uuid)","photo.v30_watermark_after_presentation_scope(uuid,uuid,integer,text,text)","photo.begin_v30_watermark_presentation_continuation(uuid,uuid,integer,text,jsonb,text,text)","photo.v30_watermark_presentation_transport_ready(uuid,uuid,integer,integer,uuid,jsonb,text,text)","photo.activate_v30_watermark_presentation(uuid,uuid,integer,integer,uuid,jsonb,text,text)","photo.v30_watermark_presentation_activated(uuid,uuid,integer,integer,uuid,jsonb,text,text)","photo.create_v30_watermark_derivative_initial_draft(uuid,uuid,integer,text,uuid,text,jsonb,text,bigint)","photo.v30_watermark_derivative_initial_transport_ready(uuid,uuid,integer,jsonb,text)","photo.activate_v30_watermark_derivative_initial_child(uuid,uuid,integer,text,uuid,text)","photo.commit_v30_watermark_derivative_initial_child(uuid,uuid,integer,text,uuid)"}{
 var owner string;var definer,public bool
 err=db.QueryRow(ctx,`SELECT r.rolname,p.prosecdef,EXISTS(SELECT FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) acl WHERE acl.grantee=0 AND acl.privilege_type='EXECUTE') FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid=$1::regprocedure`,signature).Scan(&owner,&definer,&public)
 if err!=nil||owner!="photo_fn_owner"||!definer||public{t.Fatal("function ownership/ACL",err)}
 for _,role:=range []string{"photo_scheduler","photo_api","photo_worker","photo_gateway","photo_portal"}{var allowed bool;if err=db.QueryRow(ctx,`SELECT has_function_privilege($1,$2,'EXECUTE')`,role,signature).Scan(&allowed);err!=nil||allowed!=(role=="photo_scheduler"&&signature!="photo.v30_watermark_placement_ready(bigint,bigint,bigint,bigint,jsonb)"&&signature!="photo.create_v30_watermark_sharpen_task(uuid,uuid,integer,integer,uuid,jsonb,text,bigint)"&&signature!="photo.v30_watermark_derivative_profile(text,text,text)"&&signature!="photo.create_v30_watermark_derivative_initial_draft(uuid,uuid,integer,text,uuid,text,jsonb,text,bigint)"&&signature!="photo.lock_v30_watermark_retained_source(uuid,uuid,uuid,uuid,uuid,text,text)"&&signature!="photo.v30_watermark_retained_source_ready(uuid,uuid,uuid,uuid,uuid,text,text)"&&signature!="photo.v30_watermark_encode_completion_ready(uuid,uuid,text)"&&signature!="photo.commit_v30_watermark_initial_child(uuid,uuid,integer,text,uuid)"&&signature!="photo.commit_v30_watermark_derivative_initial_child(uuid,uuid,integer,text,uuid)"&&signature!="photo.v30_watermark_after_presentation_scope(uuid,uuid,integer,text,text)"){t.Fatal(role,allowed,err)}}
 }
}
